script:
$env:Path = [System.Environment]::GetEnvironmentVariable("Path","Machine") + ";" + [System.Environment]::GetEnvironmentVariable("Path","User")
$configDir = "$env:USERPROFILE\.config\opencode"
"=== cloning shell-strategy ==="
if (-not (Test-Path "$configDir\plugin\shell-strategy")) {
  git clone https://github.com/JRedeker/opencode-shell-strategy.git "$configDir\plugin\shell-strategy" 2>&1 | Select-Object -Last 3
} else { "already cloned" }
"=== updating opencode.json to add instructions ==="
$config = Get-Content "$configDir\opencode.json" | ConvertFrom-Json
$config | Add-Member -NotePropertyName "instructions" -NotePropertyValue @("$configDir\plugin\shell-strategy\shell_strategy.md") -Force
$config | ConvertTo-Json -Depth 10 | Out-File -FilePath "$configDir\opencode.json" -Encoding utf8
"opencode.json updated with instructions"
"=== cloning superpowers ==="
if (-not (Test-Path "$configDir\skills\superpowers")) {
  git clone https://github.com/obra/superpowers.git "$configDir\skills\superpowers" 2>&1 | Select-Object -Last 3
} else { "already cloned" }
"=== verify ==="
Get-ChildItem "$configDir\plugin\shell-strategy" | Select-Object Name | Select-Object -First 5
Get-ChildItem "$configDir\skills\superpowers" | Select-Object Name | Select-Object -First 5
